    if($method==='GET'&&preg_match('#/files/([^/?]+)\?alt=media#',$url,$m)){$id=rawurldecode($m[1]);return isset($remote['files'][$id])?drive_response(200,$remote['files'][$id]['content']):drive_response(404);}
    if($method==='GET'&&preg_match('#/files/([^/?]+)\?#',$url,$m)){$id=rawurldecode($m[1]);return isset($remote['files'][$id])?drive_response(200,$remote['files'][$id]['meta']):drive_response(404);}
    if($method==='POST'&&strpos($url,'/drive/v3/files?fields=')!==false){$meta=json_decode($body,true);$meta['webViewLink']='https://drive.google.com/drive/folders/'.$meta['id'];$meta['trashed']=false;$remote['files'][$meta['id']]=array('meta'=>$meta,'content'=>'');$remote['folders']++;return drive_response(200,$meta);}
    if($method==='POST'&&strpos($url,'uploadType=resumable')!==false){$meta=json_decode($body,true);$remote['files'][$meta['id']]=array('meta'=>array_merge($meta,array('size'=>0,'md5Checksum'=>'')),'content'=>'');$session='https://www.googleapis.com/upload/drive/v3/files?upload_id='.$meta['id'];$remote['sessions'][$session]=$meta['id'];return drive_response(200,array(),array('location'=>$session));}
    if($method==='PUT'&&strpos($url,'upload_id=')!==false){$id=$remote['sessions'][$url];$file=&$remote['files'][$id];$range=$args['headers']['Content-Range']??'';if(strpos($range,'bytes */')===0){$size=(int)substr($range,8);return strlen($file['content'])===$size?drive_response(200):drive_response(308);}
        if(!preg_match('/bytes (\d+)-(\d+)\/(\d+)/',$range,$m))throw new Exception('Missing byte range');$start=(int)$m[1];if($start!==strlen($file['content']))throw new Exception('Upload repeated or skipped bytes');$file['content'].=$body;$remote['chunks']++;$size=(int)$m[3];if(strlen($file['content'])===$size){$file['meta']['size']=$size;$file['meta']['md5Checksum']=md5($file['content']);$file['meta']['webViewLink']='https://drive.google.com/file/d/'.$id.'/view';return drive_response(200,$file['meta']);}return drive_response(308,array(),array('range'=>'bytes=0-'.(strlen($file['content'])-1)));}
    if($method==='POST'&&strpos($url,'uploadType=multipart')!==false){preg_match('/boundary=([^;]+)/',$args['headers']['Content-Type'],$b);$parts=explode('--'.$b[1],$body);$meta=json_decode(trim(substr($parts[1],strpos($parts[1],"\r\n\r\n")+4)),true);$csv=substr($parts[2],strpos($parts[2],"\r\n\r\n")+4);$csv=preg_replace('/\r\n$/','',$csv);$meta['size']=strlen($csv);$meta['md5Checksum']=md5($csv);$meta['webViewLink']='https://drive.google.com/file/d/'.$meta['id'].'/view';$meta['trashed']=false;$remote['files'][$meta['id']]=array('meta'=>$meta,'content'=>$csv);$remote['register_creates']++;return drive_response(200,$meta);}
    if($method==='PATCH'&&strpos($url,'uploadType=media')!==false){preg_match('#/files/([^?]+)#',$url,$m);$id=rawurldecode($m[1]);$remote['files'][$id]['content']=$body;$remote['files'][$id]['meta']['size']=strlen($body);$remote['files'][$id]['meta']['md5Checksum']=md5($body);$remote['register_updates']++;return drive_response(200,$remote['files'][$id]['meta']);}
